function resolveEvolution(){for(const t of TRAITS)state.traits[t]=Math.min(100,state.traits[t]+(state.dreamPoints?.[t]||0));const trait=bestTrait();const [name,description]=SPECIES[trait];const foods=Object.entries(state.diet).sort((a,b)=>b[1]-a[1]);const dietText=foods.length?foods.slice(0,3).map(([f,n])=>`${f.toLowerCase()}${n>1?' (often)':''}`).join(', '):'a little of whatever the forest offers';state.lastEvolution={trait,name,description,diet:dietText};state.species=name;state.generation++;state.dreamMode=false;state.dreamPoints={};state.history.push(`The old mouse line became ${name}.`);toast('The season has shaped a new species.');render()}
function chooseAppeal(index){const appeal=APPEALS[index];state.appeal=appeal.name;state.appealScore+=5;state.history.push(`Your lineage developed ${appeal.name.toLowerCase()}.`);state.lastEvolution=null;state.actionsLeft=8;state.cycleActions=8;state.dreamIndex=0;state.scene='action';render();window.scrollTo({top:0,behavior:'smooth'})}
render();
